def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first position where chars differ
    min_len = min(len(s_in), len(s_out))

    # Check character by character
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            # Check if we're inserting or replacing
            if len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion case  
                return (s_in[i], '', i)
            else:
                # Replacement case
                return (s_in[i], s_out[i], i)

    # If we got here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insertion at end
        return (s_in[-1] if s_in else '', s_out[-1], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion at end
        return (s_in[-1], '', len(s_out))
    else:
        # Strings are identical (shouldn't happen given our changed pairs)
        return ('', '', -1)

